#!/usr/bin/env bash
# mutants.sh - pre-flight G7: break riscv.sv on purpose, one line at a time, and
# require the whole-system simulation (organisers' emu.c -> top.sv -> riscv.sv) to
# catch every break. Runs in WSL/Linux. Each mutant is generated by
# gen_riscv_sv.py (--mutate / --core-hz), built, and plays ./emu line 1 (reset, pins,
# UART both ways).
#   reset    reset polarity inverted          divider  our UART set for 250 MHz (2170)
#   txdone   o_Tx_Done never returns to 1     rxdone   o_Rx_Done a level, not a pulse
#   pins     pin direction inverted
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
LINES="$ROOT/application/emulator-preview/emu_commands.txt"
LOG="$ROOT/build/stage4/mutants.log"
: > "$LOG"
caught=0; missed=0
for m in reset divider txdone rxdone pins; do
    SV="$ROOT/build/stage4/mutants/riscv_$m.sv"
    OUT="/tmp/rvbl2_mut_$m"
    if ! bash "$ROOT/scripts/stage4/build_emu_sys.sh" "$SV" "$OUT" >> "$LOG" 2>&1; then
        echo "MUTANT $m: build failed (counts as caught by the build)" | tee -a "$LOG"; caught=$((caught+1)); continue
    fi
    (cd "$OUT" && timeout 600 ./sim_emu --lines "$LINES" --scale 0.1 --only 1 --max-access 400) >> "$LOG" 2>&1
    rc=$?
    if [ $rc -ne 0 ]; then
        why=$(grep -a -m1 -E "HANG|\[error\]|FAIL" "$LOG" | tail -1)
        echo "MUTANT $m: CAUGHT ($(grep -a -E 'HANG|\[error\]|NOT RUNNING' "$LOG" | tail -1))" | tee -a "$LOG"
        caught=$((caught+1))
    else
        echo "MUTANT $m: MISSED - the simulation passed a broken design" | tee -a "$LOG"
        missed=$((missed+1))
    fi
done
echo "==== mutants: $caught caught, $missed missed ====" | tee -a "$LOG"
[ $missed -eq 0 ] && echo "MUTANTS: ALL CAUGHT" | tee -a "$LOG"
exit $missed
